function calculateBreakeven() {
  const price = parseFloat(document.getElementById('devicePrice').value) || 0;
  const eatingOut = parseFloat(document.getElementById('eatingOutCost').value) || 0;
  const homeCook = parseFloat(document.getElementById('homeCookCost').value) || 0;
  const timesPerWeek = parseFloat(document.getElementById('timesPerWeek').value) || 0;
  const electric = parseFloat(document.getElementById('electricCost').value) || 0;

  const savePerMeal = eatingOut - (homeCook + electric);
  const resultDiv = document.getElementById('calcResult');

  if (savePerMeal <= 0) {
    resultDiv.innerHTML = '<div class="result-headline">結論：<strong>外食費より自炊費が高いため、金銭的な元は取れません</strong></div><p style="color: #666; margin-top: 8px; font-size: 0.9rem;">1食あたりの自炊食材費を見直すか、浮いた時間（タイムパフォーマンス）を重視して導入を検討しましょう。</p>';
    return;
  }

  const weeklySavings = savePerMeal * timesPerWeek;
  const monthlySavings = Math.round(weeklySavings * 4.333);
  const yearlySavings = monthlySavings * 12;
  const monthsToBreakeven = (price / monthlySavings).toFixed(1);
  const firstYearProfit = yearlySavings - price;

  resultDiv.innerHTML = `
    <div class="result-headline">結論：約 <strong>${monthsToBreakeven} ヶ月</strong> で本体代の元が取れます！</div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>月間の節約額</span>
        <strong>約 ${monthlySavings.toLocaleString()} 円</strong>
        <small>週 ${timesPerWeek} 回の自炊化ベース</small>
      </div>
      <div class="metric-card">
        <span>年間浮く食費</span>
        <strong>約 ${yearlySavings.toLocaleString()} 円</strong>
        <small>12ヶ月換算の純節約額</small>
      </div>
      <div class="metric-card">
        <span>1年目の実質収支</span>
        <strong>${firstYearProfit >= 0 ? '+' : ''}${firstYearProfit.toLocaleString()} 円</strong>
        <small>本体購入費を差し引いた差額</small>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', calculateBreakeven);
